				const { getOctoCodeRuntime } = await import("../../services/octocode-runtime/OctoCodeRuntime")
				const runtime = getOctoCodeRuntime()
				const session = await runtime.call("session.get", { id: sessionId })
				const rows = await runtime.call("event.list", { session_id: sessionId })
				const messages = await runtime.call("message.list", { session_id: sessionId })
				if (
					!session ||
					typeof session !== "object" ||
					Array.isArray(session) ||
					!Array.isArray(rows) ||
					!Array.isArray(messages)
				) {
					throw new Error("Runtime session is unavailable")
				}
				const record = session as Record<string, unknown>
				const userMessages = messages.flatMap((message) => {
					if (!message || typeof message !== "object" || Array.isArray(message)) return []
					const value = message as Record<string, unknown>
					return value.role === "user" && typeof value.content === "string" ? [value.content] : []
				})
				let taskId = sessionId
				for (const row of rows) {
					if (!Array.isArray(row) || typeof row[1] !== "string") continue
					const payload = row[2]
					if (
						(row[1] === "harness.prepared" || row[1] === "harness.continued") &&
						payload &&
						typeof payload === "object" &&
						!Array.isArray(payload) &&
						typeof (payload as Record<string, unknown>).task_id === "string"
					) {
						taskId = (payload as Record<string, unknown>).task_id as string
					}
				}
				let continuationIndex = 1
				const events = rows.flatMap((row) => {
					if (!Array.isArray(row) || typeof row[1] !== "string") return []
					const event = { task_id: taskId, session_id: sessionId, kind: row[1], payload: row[2] }
					if (row[1] !== "harness.continued" || continuationIndex >= userMessages.length) return [event]
					return [
						{
							task_id: taskId,
							session_id: sessionId,
							kind: "user.message",
							payload: { text: userMessages[continuationIndex++] },
						},
						event,
					]
				})
				const response = {
					type: "runtimeSessionLoaded" as const,
					payload: {
						prompt: userMessages[0] ?? (typeof record.title === "string" ? record.title : sessionId),
						sessionId,
						taskId,
						status: typeof record.status === "string" ? record.status : undefined,
						phase: record.phase === "executing" || record.phase === "thinking" ? record.phase : undefined,
						events,
